#!/usr/bin/env bash
# Remote C++ build + seam tests for OpenSky-art-v2 on swat-worker (keeps the laptop cool).
# Canonical copy (WP17); runs the three test binaries then ctest (sim goldens) so goldens cannot go stale unnoticed.
# Usage: rb-cpp.sh [targets...]   (default: OpenSkyscraper OpenSkyTests)   Env: RB_JOBS (default 4)
set -euo pipefail
H=worker@192.168.5.169; SRC="${RB_SRC:-$HOME/Projects/OpenSky-art-v2}"; NAME=$(basename "$SRC"); T="${*:-OpenSkyscraper OpenSkyTests OpenSkyTransportTests OpenSkyDisasterTests}"; J="${RB_JOBS:-4}"
rsync -az --delete --exclude build --exclude 'build-*' --exclude 'debug-*.log' --exclude 'b-*' -e "ssh -o BatchMode=yes" "$SRC" $H:~/Projects/ 
ssh -o BatchMode=yes $H "set -e; cd ~/Projects/$NAME; nice -n 10 cmake -S . -B build -G Ninja -DCMAKE_BUILD_TYPE=Debug >/dev/null; nice -n 10 cmake --build build -j$J --target $T 2>&1 | grep -E 'error|warning:|FAILED|ninja: build stopped|Linking' || true; echo BUILD_EXIT=\${PIPESTATUS[0]}; if echo '$T' | grep -q OpenSkyTests; then cd build && xvfb-run -a ./OpenSkyTests > /tmp/oskytests.log 2>&1; rc=\$?; grep -E 'FAIL|tests? failed|All tests passed' /tmp/oskytests.log | tail -8; echo TEST_EXIT=\$rc; if [ -x ./OpenSkyTransportTests ]; then xvfb-run -a ./OpenSkyTransportTests > /tmp/oskytransport.log 2>&1; rc2=\$?; grep -E 'FAIL|SKIP|tests? failed|All tests passed' /tmp/oskytransport.log | tail -6; echo TRANSPORT_TEST_EXIT=\$rc2; fi; if [ -x ./OpenSkyDisasterTests ]; then xvfb-run -a ./OpenSkyDisasterTests > /tmp/oskydisaster.log 2>&1; rc3=\$?; grep -v miniaudio /tmp/oskydisaster.log | grep -E 'FAIL|checks|passed|failed' | tail -4; echo DISASTER_TEST_EXIT=\$rc3; fi; nice -n 10 cmake --build . -j$J --target OpenSkyscraper >/dev/null 2>&1 || true; xvfb-run -a ctest --output-on-failure > /tmp/oskyctest.log 2>&1; rc4=\$?; tail -40 /tmp/oskyctest.log; echo CTEST_EXIT=\$rc4; fi"
